const maps={world:{name:'World Tour',size:40,cities:['Dublin','Lisbon','Barcelona','Paris','London','Amsterdam','Rome','Berlin','Prague','Vienna','Athens','Istanbul','Cairo','Cape Town','Dubai','Mumbai','Bangkok','Singapore','Seoul','Tokyo','Sydney','Auckland','Vancouver','New York','Mexico City','Rio','Buenos Aires','Toronto']},europe:{name:'Grand Europe',size:48,cities:['Dublin','Cork','Edinburgh','London','Bath','Lisbon','Porto','Madrid','Barcelona','Paris','Lyon','Nice','Brussels','Amsterdam','Copenhagen','Oslo','Stockholm','Helsinki','Berlin','Munich','Prague','Vienna','Budapest','Venice','Florence','Rome','Naples','Athens','Split','Dubrovnik','Zurich','Geneva','Krakow','Warsaw','Tallinn','Reykjavik']},mega:{name:'Global Empire',size:64,cities:['Dublin','Lisbon','Porto','Madrid','Barcelona','Paris','London','Amsterdam','Copenhagen','Stockholm','Berlin','Prague','Vienna','Zurich','Rome','Venice','Athens','Istanbul','Marrakesh','Cairo','Nairobi','Cape Town','Dubai','Doha','Mumbai','Delhi','Jaipur','Bangkok','Hanoi','Bali','Singapore','Hong Kong','Shanghai','Beijing','Taipei','Seoul','Kyoto','Tokyo','Sydney','Melbourne','Auckland','Honolulu','Vancouver','San Francisco','Los Angeles','Chicago','Toronto','New York','Miami','Mexico City','Havana','Lima','Rio','Buenos Aires']}};
maps.classic={name:'Classic',size:40,cities:[]};
const classicNames=['START','Salvador','Treasure','Rio','Earnings Tax','TLV Airport','Tel Aviv','Haifa','Surprise','Jerusalem','In Prison','Venice','Power Company','Milan','Rome','MUC Airport','Frankfurt','Treasure','Munich','Berlin','Vacation','Shenzhen','Surprise','Beijing','Shanghai','CDG Airport','Lyon','Water Company','Toulouse','Paris','Go to prison','Liverpool','Manchester','Treasure','London','JFK Airport','Surprise','San Francisco','Premium Tax','New York'];
const prices=[0,60,0,60,0,200,100,110,0,120,0,130,150,140,160,200,180,0,190,200,0,210,0,220,240,200,260,150,270,280,0,290,300,0,320,200,0,360,0,400];
const groups={1:0,3:0,6:1,7:1,9:1,11:2,13:2,14:2,16:3,18:3,19:3,21:4,23:4,24:4,26:5,28:5,29:5,31:6,32:6,34:6,37:7,39:7};
const rents={1:[2,10,30,90,160,250],3:[4,20,60,180,320,450],6:[6,30,90,270,400,550],7:[6,30,90,270,400,550],9:[8,40,100,300,450,600],11:[10,50,150,450,625,750],13:[10,50,150,450,625,750],14:[12,60,180,500,700,900],16:[14,70,200,550,750,950],18:[14,70,200,550,750,950],19:[16,80,220,600,800,1000],21:[18,90,250,700,875,1050],23:[18,90,250,700,875,1050],24:[20,100,300,750,925,1100],26:[22,110,330,800,975,1150],28:[22,110,330,800,975,1150],29:[24,120,360,850,1025,1200],31:[26,130,390,900,1100,1275],32:[26,130,390,900,1100,1275],34:[28,150,450,1000,1200,1400],37:[35,175,500,1100,1300,1500],39:[50,200,600,1400,1700,2000]};
function boardFor(key){if(key==='classic')return classicNames.map((name,i)=>({id:i,name,type:i===0?'go':i===10?'jail':i===20?'park':i===30?'gojail':i===4||i===38?'tax':[5,15,25,35].includes(i)?'station':[12,27].includes(i)?'utility':[2,8,17,22,33,36].includes(i)?'event':'property',group:groups[i]??-1,price:prices[i],rent:rents[i]?.[0]||25,rents:rents[i],buildCost:50*(1+Math.floor((groups[i]||0)/2)),flag:groups[i]===undefined?'':['🇧🇷','🇮🇱','🇮🇹','🇩🇪','🇨🇳','🇫🇷','🇬🇧','🇺🇸'][groups[i]]}));const m=maps[key];let city=0;return Array.from({length:m.size},(_,i)=>{const q=m.size/4;let type=i===0?'go':i===q?'jail':i===q*2?'park':i===q*3?'gojail':i%q===Math.floor(q/2)?'station':i%9===3?'event':i%13===4?'tax':'property';return {id:i,type,name:type==='property'?m.cities[city++%m.cities.length]:({go:'START',jail:'In Prison',park:'Vacation',gojail:'Go to prison',station:'Airport',event:i%2?'Treasure':'Surprise',tax:'City tax'})[type],group:Math.floor(i/4),price:100+Math.floor(i/4)*35,rent:12+Math.floor(i/4)*5};});}
function createGame(map='world',rules={}){if(!maps[map])throw Error('Unknown map');return {map,rules:{salary:200,startCash:1500,events:true,freeParking:false,roundLimit:0,maxPlayers:4,doubleRent:false,noPrisonRent:false,mortgage:false,evenBuild:true,auction:false,randomOrder:true,...rules},players:[],status:'lobby',turn:0,phase:'roll',round:1,dice:[1,1],doubles:0,properties:{},log:['Room created. Invite your friends.'],chat:[],pot:0,pending:null,trade:null};}
function log(g,s){g.log.unshift(s);g.log=g.log.slice(0,40);}
function requireThat(c,s){if(!c)throw Error(s);}
function pay(g,p,amount,to){p.cash-=amount;if(to)to.cash+=amount;else g.pot+=amount;}
function finish(g){const alive=g.players.filter(x=>!x.out);if(alive.length===1){g.status='finished';g.winner=alive[0].id;log(g,alive[0].name+' wins!');}}
function act(g,id,a,random=()=>{const n=new Uint32Array(1);crypto.getRandomValues(n);return n[0]/4294967296;}){const p=g.players.find(x=>x.id===id);requireThat(p,'Join this room first');const board=boardFor(g.map);const current=g.players[g.turn];const own=(i)=>g.properties[i];const full=(group)=>board.filter(t=>t.type==='property'&&t.group===group).every(t=>own(t.id)?.owner===id);const add=(s)=>log(g,s);
if(a.type==='bots'){requireThat(g.status==='lobby'&&g.players[0].id===id,'Only the host can change bots');g.players=g.players.filter(x=>!x.bot);g.rules.allowBots=!!a.enabled;if(a.enabled)while(g.players.length<g.rules.maxPlayers){const n=g.players.length;g.players.push({id:crypto.randomUUID(),name:['Bright Fox','Quiet Moon','Lucky Cloud','Swift Pine','Tiny Star','Wild Owl','Soft Rain'][n-1],bot:true,color:n,pos:0,cash:g.rules.startCash,jail:0,out:false});}return;}
if(a.type==='chat'){const text=String(a.text||'').trim().slice(0,300);requireThat(text,'Enter a message');g.chat??=[];g.chat.push({name:p.name,text});g.chat=g.chat.slice(-80);return;}
if(a.type==='appearance'){requireThat(Number.isInteger(a.color)&&a.color>=0&&a.color<12,'Choose a color');p.color=a.color;return;}
if(a.type==='settings'){requireThat(p.id===g.players[0].id&&g.status==='lobby','Only the host can change lobby settings');if(a.map){requireThat(!!maps[a.map],'Unknown map');g.map=a.map;}for(const k of ['doubleRent','freeParking','auction','noPrisonRent','mortgage','evenBuild','randomOrder','events'])if(k in (a.rules||{}))g.rules[k]=!!a.rules[k];for(const [k,choices]of [['startCash',[500,1000,1500,2000,2500,3000]],['maxPlayers',[2,3,4,5,6,7,8]]])if(k in (a.rules||{})){requireThat(choices.includes(+a.rules[k]),'Invalid setting');requireThat(k!=='maxPlayers'||+a.rules[k]>=g.players.length,'Players already joined');g.rules[k]=+a.rules[k];}return;}
if(a.type==='start'){requireThat(p.id===g.players[0].id,'Only the host can start');requireThat(g.status==='lobby'&&g.players.length>=2,'Need at least two players');g.status='playing';if(g.rules.randomOrder){for(let i=g.players.length-1;i>0;i--){const j=Math.floor(random()*(i+1));[g.players[i],g.players[j]]=[g.players[j],g.players[i]];}}g.players.forEach(x=>x.cash=g.rules.startCash);add('The game begins. '+g.players[0].name+' rolls first.');return;}
requireThat(g.status==='playing'&&!p.out,'Game is not active');
if(a.type==='bid'||a.type==='passAuction'){const au=g.auction;requireThat(g.phase==='auction'&&au&&au.order[au.index]===id,'Wait for your auction bid');if(a.type==='bid'){const n=Number(a.amount);requireThat(Number.isInteger(n)&&n>au.bid&&n<=p.cash,'Bid must be higher and affordable');au.bid=n;au.winner=id;}else au.passed.push(id);const bidders=au.order.filter(x=>!au.passed.includes(x));if(!bidders.length||(bidders.length===1&&au.winner===bidders[0])){if(au.winner){g.properties[au.tile]={owner:au.winner,level:0,mortgaged:false};g.players.find(x=>x.id===au.winner).cash-=au.bid;add('Auction won for $'+au.bid);}g.auction=null;g.phase='end';}else{do{au.index=(au.index+1)%au.order.length;}while(au.passed.includes(au.order[au.index]));}return;}
requireThat(g.phase!=='auction','Finish the auction first');
if(a.type==='trade'){requireThat(!g.trade,'Resolve the existing offer');const target=g.players.find(x=>x.id===a.target&&!x.out&&x.id!==id);requireThat(target,'Choose another player');const give=Number(a.giveCash),take=Number(a.takeCash);requireThat(Number.isInteger(give)&&give>=0&&give<=p.cash&&Number.isInteger(take)&&take>=0&&take<=target.cash,'Invalid cash offer');const gp=Number(a.giveProperty),tp=Number(a.takeProperty);requireThat((gp===-1||own(gp)?.owner===id&&!own(gp).level)&&(tp===-1||own(tp)?.owner===target.id&&!own(tp).level),'Only undeveloped owned properties can be traded');g.trade={from:id,to:target.id,give,take,gp,tp};add(p.name+' proposed a trade.');return;}
if(a.type==='rejectTrade'){requireThat(g.trade&&(g.trade.to===id||g.trade.from===id),'No offer');g.trade=null;return;}
if(a.type==='acceptTrade'){const t=g.trade;requireThat(t?.to===id,'No trade for you');const from=g.players.find(x=>x.id===t.from);requireThat(from.cash>=t.give&&p.cash>=t.take&&(t.gp===-1||own(t.gp)?.owner===from.id)&&(t.tp===-1||own(t.tp)?.owner===id),'Offer no longer valid');from.cash+=t.take-t.give;p.cash+=t.give-t.take;if(t.gp!==-1)own(t.gp).owner=id;if(t.tp!==-1)own(t.tp).owner=from.id;g.trade=null;add('Trade completed.');return;}
requireThat(current.id===id,'Wait for your turn');
if(a.type==='build'){const t=board[Number(a.tile)],o=own(t?.id);requireThat(t?.type==='property'&&o?.owner===id&&full(t.group)&&!board.some(x=>x.group===t.group&&own(x.id)?.mortgaged),'Own an unmortgaged city set first');const level=o.level||0,cost=t.buildCost||Math.ceil(t.price/2);requireThat(level<5&&p.cash>=cost,'Cannot afford more buildings');requireThat(!g.rules.evenBuild||board.filter(x=>x.type==='property'&&x.group===t.group).every(x=>(own(x.id).level||0)>=level),'Build evenly across the set');p.cash-=cost;o.level=level+1;add(p.name+' developed '+t.name);return;}
if(a.type==='mortgage'){requireThat(g.rules.mortgage,'Mortgage is disabled in this room');const t=board[Number(a.tile)],o=own(t?.id);requireThat(o?.owner===id&&!board.some(x=>x.group===t.group&&(own(x.id)?.level||0)>0),'Sell buildings in this set first');const cost=Math.floor(t.price/2);if(o.mortgaged){requireThat(p.cash>=Math.ceil(cost*1.1),'Not enough cash');p.cash-=Math.ceil(cost*1.1);o.mortgaged=false;}else{p.cash+=cost;o.mortgaged=true;}return;}
if(a.type==='sellBuilding'){const t=board[Number(a.tile)],o=own(t?.id);requireThat(o?.owner===id&&o.level>0,'No building to sell');requireThat(!g.rules.evenBuild||board.filter(x=>x.type==='property'&&x.group===t.group).every(x=>(own(x.id)?.level||0)<=o.level),'Sell evenly across the set');o.level--;p.cash+=Math.floor((t.buildCost||Math.ceil(t.price/2))/2);return;}
if(a.type==='bankrupt'){requireThat(p.cash<0,'Bankruptcy requires debt');p.out=true;for(const [i,o]of Object.entries(g.properties))if(o.owner===id)delete g.properties[i];g.trade=null;add(p.name+' is bankrupt.');finish(g);if(g.status==='playing')next();return;}
if(a.type==='bail'){requireThat(p.jail>0&&g.phase==='roll'&&p.cash>=50,'Bail unavailable');p.cash-=50;p.jail=0;add(p.name+' paid bail.');return;}
if(a.type==='buy'){requireThat(g.phase==='buy','No property for sale');const t=board[p.pos];requireThat(!own(t.id)&&p.cash>=t.price,'Cannot afford this property');p.cash-=t.price;g.properties[t.id]={owner:id,level:0,mortgaged:false};g.phase='end';add(p.name+' bought '+t.name);return;}
if(a.type==='skip'){requireThat(g.phase==='buy','No purchase pending');if(g.rules.auction){g.phase='auction';g.auction={tile:p.pos,bid:0,winner:null,index:0,order:g.players.filter(x=>!x.out&&x.cash>0).map(x=>x.id),passed:[]};requireThat(g.auction.order.length>0,'No solvent bidders');add('Auction started for '+board[p.pos].name);}else g.phase='end';return;}
if(a.type==='end'){requireThat(g.phase==='end'&&p.cash>=0,'Resolve your turn and debts first');if(g.doubles&&p.jail===0){g.phase='roll';add(p.name+' rolls again for doubles.');}else next();return;}
requireThat(a.type==='roll'&&g.phase==='roll','Roll is unavailable');requireThat(p.cash>=0,'Resolve debts first');g.dice=[1+Math.floor(random()*6),1+Math.floor(random()*6)];const doubles=g.dice[0]===g.dice[1];g.doubles=doubles?g.doubles+1:0;g.phase='end';if(g.doubles===3){jail();return;}
if(p.jail){p.jail--;if(doubles){p.jail=0;g.doubles=0;add(p.name+' rolled out of jail.');}else if(p.jail>0){add(p.name+' stays in jail.');return;}else{pay(g,p,50);add(p.name+' paid $50 to leave jail.');}}
const old=p.pos;p.pos=(old+g.dice[0]+g.dice[1])%board.length;if(p.pos<old){p.cash+=g.rules.salary;add(p.name+' collected $'+g.rules.salary);}
const t=board[p.pos];add(p.name+' landed on '+t.name);if(t.type==='gojail'){jail();return;}if(t.type==='tax'){const tax=g.map==='classic'?(t.id===4?Math.floor(Math.max(p.cash,0)*.1):75):100;pay(g,p,tax);add('Tax: $'+tax);}if(t.type==='park'&&g.rules.freeParking){p.cash+=g.pot;add('Vacation cash: $'+g.pot);g.pot=0;}if(t.type==='event'&&g.rules.events){const amount=random()<.5?100:-75;p.cash+=amount;add(amount>0?'City festival bonus: $100':'Street repairs: pay $75');}
if(['property','station','utility'].includes(t.type)){const o=own(t.id);if(!o){g.phase='buy';}else if(o.owner!==id&&!o.mortgaged){const owner=g.players.find(x=>x.id===o.owner);if(owner.jail&&g.rules.noPrisonRent)return;const level=o.level||0;const stations=board.filter(x=>x.type==='station'&&own(x.id)?.owner===owner.id).length;const utilities=board.filter(x=>x.type==='utility'&&own(x.id)?.owner===owner.id).length;const rent=t.type==='utility'?(utilities===2?10:4)*(g.dice[0]+g.dice[1]):t.type==='station'?25*Math.pow(2,stations-1):(t.rents?t.rents[level]:t.rent*[1,3,8,15,25,40][level])*(g.rules.doubleRent&&level===0&&board.filter(x=>x.type==='property'&&x.group===t.group).every(x=>own(x.id)?.owner===owner.id)?2:1);pay(g,p,rent,owner);add(p.name+' paid $'+rent+' rent to '+owner.name);}}
function jail(){p.pos=board.length/4;p.jail=3;g.doubles=0;g.phase='end';add(p.name+' went to jail.');}
function next(){g.doubles=0;g.trade=null;let next=g.turn;do{next=(next+1)%g.players.length;if(next===0)g.round++;}while(g.players[next].out);g.turn=next;g.phase='roll';if(g.rules.roundLimit&&g.round>g.rules.roundLimit){g.status='finished';g.winner=g.players.filter(x=>!x.out).sort((a,b)=>worth(b)-worth(a))[0].id;add('Round limit reached. Highest net worth wins.');}}
function worth(x){return x.cash+Object.entries(g.properties).filter(([,o])=>o.owner===x.id).reduce((sum,[i,o])=>sum+board[i].price*(o.mortgaged?.5:1)+(o.level||0)*Math.ceil(board[i].price/2),0);}
}

